    // Diagnostic A/B: retain shader compilation but use descriptor bindings.
    static const bool descriptor_only_a82d2fe = [] {
        const char* value = std::getenv("RYGT_A82D2FE_DESCRIPTOR_ONLY");
        return value && value[0] == '1';
    }();
